select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id": 9447, "materia": "aud", "nivel": 0, "enunciado": "O objetivo da auditoria das demonstrações contábeis é:", "opcoes": ["Aumentar a confiança dos usuários por meio da opinião do auditor", "Fazer a contabilidade da empresa", "Calcular os impostos", "Punir os administradores"], "explicacao": "NBC TA 200."}, {"id": 9448, "materia": "aud", "nivel": 0, "enunciado": "A diferença entre erro e fraude é que a fraude é:", "opcoes": ["Intencional", "Sempre pequena", "Involuntária", "Sempre de cálculo"], "explicacao": "NBC TA 240."}, {"id": 9449, "materia": "aud", "nivel": 0, "enunciado": "A segurança dada pelo auditor sobre as demonstrações é:", "opcoes": ["Razoável, não absoluta", "Absoluta", "Nenhuma", "Total para fraudes"], "explicacao": "NBC TA 200."}, {"id": 9450, "materia": "aud", "nivel": 0, "enunciado": "A separação de funções incompatíveis, como autorizar e pagar, é exemplo de:", "opcoes": ["Controle interno (segregação de funções)", "Fraude", "Erro contábil", "Auditoria externa"], "explicacao": ""}, {"id": 9451, "materia": "aud", "nivel": 1, "enunciado": "O ceticismo profissional do auditor envolve:", "opcoes": ["Mente questionadora e avaliação crítica das evidências", "Acreditar em tudo o que a administração diz", "Desconfiar de tudo sem critério", "Aceitar só documentos internos"], "explicacao": "NBC TA 200."}, {"id": 9452, "materia": "aud", "nivel": 1, "enunciado": "O triângulo da fraude é formado por:", "opcoes": ["Pressão (incentivo), oportunidade e racionalização", "Erro, culpa e dolo", "Ativo, passivo e PL", "Planejamento, execução e relatório"], "explicacao": ""}, {"id": 9453, "materia": "aud", "nivel": 1, "enunciado": "A materialidade (relevância) em auditoria refere-se a distorções que:", "opcoes": ["Podem influenciar as decisões dos usuários", "São sempre de valor alto em reais", "Não importam", "Só envolvem impostos"], "explicacao": "NBC TA 320."}, {"id": 9454, "materia": "aud", "nivel": 1, "enunciado": "A circularização (confirmação externa) consiste em:", "opcoes": ["Pedir confirmação diretamente a terceiros, como clientes e bancos", "Contar o caixa", "Recalcular a depreciação", "Entrevistar o contador"], "explicacao": "NBC TA 505."}, {"id": 9455, "materia": "aud", "nivel": 1, "enunciado": "Na confirmação positiva, o terceiro deve responder:", "opcoes": ["Em qualquer caso, concordando ou não", "Só se discordar", "Nunca", "Só por telefone"], "explicacao": ""}, {"id": 9456, "materia": "aud", "nivel": 1, "enunciado": "Na confirmação negativa, o terceiro responde:", "opcoes": ["Só se discordar das informações", "Sempre", "Só se concordar", "Nunca"], "explicacao": ""}, {"id": 9457, "materia": "aud", "nivel": 1, "enunciado": "Acompanhar a contagem física de estoques feita pelos empregados é um procedimento de:", "opcoes": ["Observação", "Recálculo", "Confirmação externa", "Indagação"], "explicacao": ""}, {"id": 9458, "materia": "aud", "nivel": 2, "enunciado": "O risco de auditoria é composto por:", "opcoes": ["Risco de distorção relevante (inerente e de controle) e risco de detecção", "Apenas risco de fraude", "Risco de mercado e de crédito", "Risco de câmbio"], "explicacao": "NBC TA 200."}, {"id": 9459, "materia": "aud", "nivel": 2, "enunciado": "Quanto maior o risco de distorção relevante avaliado, o risco de detecção aceitável deve ser:", "opcoes": ["Menor, exigindo mais evidência", "Maior", "Igual", "Ignorado"], "explicacao": ""}, {"id": 9460, "materia": "aud", "nivel": 2, "enunciado": "A evidência documental é, em geral, mais confiável que a:", "opcoes": ["Oral", "Obtida pelo auditor", "Externa", "Original"], "explicacao": "NBC TA 500."}, {"id": 9461, "materia": "aud", "nivel": 2, "enunciado": "As qualidades exigidas da evidência de auditoria são:", "opcoes": ["Suficiência e adequação", "Rapidez e baixo custo", "Volume e beleza", "Sigilo e simplicidade"], "explicacao": "NBC TA 500."}, {"id": 9462, "materia": "aud", "nivel": 2, "enunciado": "Os testes de controle servem para:", "opcoes": ["Avaliar a eficácia operacional dos controles internos", "Detectar diretamente distorções nos saldos", "Calcular impostos", "Fazer o balanço"], "explicacao": "NBC TA 330."}, {"id": 9463, "materia": "aud", "nivel": 2, "enunciado": "Os procedimentos substantivos servem para:", "opcoes": ["Detectar distorções relevantes nas afirmações", "Avaliar apenas controles", "Contratar auditores", "Emitir notas fiscais"], "explicacao": "NBC TA 330."}, {"id": 9464, "materia": "aud", "nivel": 2, "enunciado": "Os componentes do controle interno pelo COSO são:", "opcoes": ["Ambiente de controle, avaliação de riscos, atividades de controle, informação e comunicação e monitoramento", "Ativo, passivo e PL", "Receita, custo e despesa", "Planejar, organizar e dirigir"], "explicacao": ""}, {"id": 9465, "materia": "aud", "nivel": 3, "enunciado": "A afirmação de existência é testada, em geral, partindo:", "opcoes": ["Do registro contábil para o item físico ou documento", "Do documento para o registro", "Do relatório para o contrato", "Da nota fiscal para o cliente sem registro"], "explicacao": "Teste de superavaliação."}, {"id": 9466, "materia": "aud", "nivel": 3, "enunciado": "A afirmação de integralidade é testada, em geral, partindo:", "opcoes": ["Do documento ou item físico para o registro contábil", "Do registro para o documento", "Do balanço para a DRE", "Da opinião do auditor"], "explicacao": "Teste de subavaliação."}, {"id": 9467, "materia": "aud", "nivel": 3, "enunciado": "A busca de passivos não registrados testa principalmente a afirmação de:", "opcoes": ["Integralidade", "Existência", "Avaliação", "Ocorrência"], "explicacao": ""}, {"id": 9468, "materia": "aud", "nivel": 3, "enunciado": "Os principais assuntos de auditoria (PAA) são obrigatórios no relatório de:", "opcoes": ["Entidades listadas (companhias abertas)", "Microempresas", "Pessoas físicas", "Órgãos públicos municipais"], "explicacao": "NBC TA 701."}, {"id": 9469, "materia": "aud", "nivel": 3, "enunciado": "A carta de representação é:", "opcoes": ["Declaração escrita da administração confirmando certos assuntos", "Contrato de auditoria", "Relatório final", "Carta ao fisco"], "explicacao": "NBC TA 580."}, {"id": 9470, "materia": "aud", "nivel": 4, "enunciado": "Na amostragem, o risco de aceitação incorreta afeta a:", "opcoes": ["Eficácia da auditoria", "Eficiência apenas", "Independência", "Remuneração do auditor"], "explicacao": "NBC TA 530."}, {"id": 9471, "materia": "aud", "nivel": 4, "enunciado": "O evento subsequente que evidencia condição já existente na data do balanço, como a falência de cliente com dívida antiga:", "opcoes": ["Gera ajuste nas demonstrações", "Só gera divulgação", "Não tem efeito", "Gera nova auditoria"], "explicacao": "NBC TA 560 e CPC 24."}, {"id": 9472, "materia": "aud", "nivel": 4, "enunciado": "Um incêndio que destrói a fábrica após a data do balanço é evento subsequente que:", "opcoes": ["Não gera ajuste, mas pode exigir divulgação", "Gera ajuste no balanço", "Anula as demonstrações", "Gera opinião adversa automática"], "explicacao": "CPC 24."}, {"id": 9473, "materia": "aud", "nivel": 4, "enunciado": "O prazo mínimo de guarda dos papéis de trabalho do auditor independente é de:", "opcoes": ["5 anos", "2 anos", "10 anos", "1 ano"], "explicacao": "NBC TA 230 e NBC PA 01."}, {"id": 9474, "materia": "aud", "nivel": 4, "enunciado": "A rotação de auditores independentes de companhias abertas, pela CVM, ocorre, em regra, a cada:", "opcoes": ["5 anos consecutivos, com intervalo mínimo de 3 anos", "2 anos", "10 anos sem exceção", "Nunca"], "explicacao": "Resolução CVM 23/2021; até 10 anos com comitê de auditoria estatutário."}, {"id": 9475, "materia": "aud", "nivel": 4, "enunciado": "São ameaças à independência do auditor:", "opcoes": ["Interesse próprio, autorrevisão, defesa, familiaridade e intimidação", "Experiência e competência", "Ceticismo e julgamento", "Planejamento e supervisão"], "explicacao": ""}, {"id": 9476, "materia": "aud", "nivel": 4, "enunciado": "O auditor deve presumir, salvo justificativa documentada, que há risco de fraude em:", "opcoes": ["Reconhecimento de receita", "Contagem de caixa", "Pagamento de salários", "Folha de ponto"], "explicacao": "NBC TA 240."}, {"id": 9477, "materia": "aud", "nivel": 4, "enunciado": "Na auditoria do setor público, a auditoria operacional avalia:", "opcoes": ["Economicidade, eficiência, eficácia e efetividade", "Apenas as demonstrações contábeis", "Só a legalidade", "A vida pessoal dos servidores"], "explicacao": ""}, {"id": 9478, "materia": "aud", "nivel": 4, "enunciado": "Pela Constituição, o responsável pelo controle interno que souber de irregularidade e não comunicar ao Tribunal de Contas:", "opcoes": ["Responde solidariamente", "Não tem responsabilidade", "É promovido", "Só recebe advertência verbal"], "explicacao": "CF, art. 74, § 1º."}, {"id": 9479, "materia": "aud", "nivel": 4, "enunciado": "O auditor independente pode usar o trabalho da auditoria interna, mas:", "opcoes": ["A responsabilidade pela opinião continua sendo exclusivamente dele", "Divide a responsabilidade com a auditoria interna", "Fica dispensado de testes", "Não precisa avaliar a auditoria interna"], "explicacao": "NBC TA 610."}, {"id": 9480, "materia": "aud", "nivel": 3, "enunciado": "O modelo das três linhas (IIA) coloca a auditoria interna na:", "opcoes": ["Terceira linha, com avaliação independente", "Primeira linha", "Segunda linha", "Fora da organização"], "explicacao": ""}, {"id": 9481, "materia": "aud", "nivel": 2, "enunciado": "O controle preventivo busca:", "opcoes": ["Evitar que o erro ocorra", "Descobrir o erro depois", "Punir o erro", "Esconder o erro"], "explicacao": ""}, {"id": 9482, "materia": "aud", "nivel": 2, "enunciado": "A conciliação bancária é exemplo de controle:", "opcoes": ["Detectivo", "Preventivo", "Corretivo apenas", "Proibido"], "explicacao": ""}, {"id": 9483, "materia": "aud", "nivel": 1, "enunciado": "Recálculo, em auditoria, é:", "opcoes": ["Verificar a exatidão matemática de documentos ou registros", "Refazer o balanço", "Contar estoques", "Entrevistar funcionários"], "explicacao": ""}, {"id": 9484, "materia": "aud", "nivel": 1, "enunciado": "Indagação, em auditoria, é:", "opcoes": ["Buscar informações com pessoas de dentro ou de fora da entidade", "Contar o estoque", "Recalcular a folha", "Enviar carta ao banco"], "explicacao": "Sozinha, normalmente não é evidência suficiente."}, {"id": 9485, "materia": "adua", "nivel": 0, "enunciado": "Portos, aeroportos e pontos de fronteira alfandegados formam a zona:", "opcoes": ["Primária", "Secundária", "Franca", "Neutra"], "explicacao": "Regulamento Aduaneiro, art. 3º."}, {"id": 9486, "materia": "adua", "nivel": 0, "enunciado": "O órgão que fiscaliza as operações de comércio exterior no Brasil é a:", "opcoes": ["Receita Federal", "Polícia Militar", "Anvisa apenas", "Prefeitura"], "explicacao": ""}, {"id": 9487, "materia": "adua", "nivel": 0, "enunciado": "O sistema informatizado de comércio exterior do Brasil é o:", "opcoes": ["Siscomex", "Siafi", "Sisu", "e-SUS"], "explicacao": ""}, {"id": 9488, "materia": "adua", "nivel": 0, "enunciado": "Contrabando é a importação ou exportação de mercadoria:", "opcoes": ["Proibida", "Permitida sem pagar imposto", "Pequena", "Com nota fiscal"], "explicacao": "CP, art. 334-A."}, {"id": 9489, "materia": "adua", "nivel": 0, "enunciado": "Descaminho é:", "opcoes": ["Iludir o pagamento de tributo devido na entrada ou saída de mercadoria permitida", "Importar mercadoria proibida", "Exportar legalmente", "Pagar imposto em dobro"], "explicacao": "CP, art. 334."}, {"id": 9490, "materia": "adua", "nivel": 1, "enunciado": "A base de cálculo do imposto de importação com alíquota ad valorem é o:", "opcoes": ["Valor aduaneiro", "Preço de venda no Brasil", "Peso da mercadoria", "Valor do frete apenas"], "explicacao": "Regulamento Aduaneiro, art. 75."}, {"id": 9491, "materia": "adua", "nivel": 1, "enunciado": "O primeiro método de valoração aduaneira é o:", "opcoes": ["Valor de transação", "Valor de mercadorias similares", "Método dedutivo", "Método computado"], "explicacao": "Acordo de Valoração Aduaneira, art. 1º."}, {"id": 9492, "materia": "adua", "nivel": 1, "enunciado": "A nomenclatura usada para classificar mercadorias no Mercosul é a:", "opcoes": ["NCM", "CNAE", "CBO", "CID"], "explicacao": "Baseada no Sistema Harmonizado."}, {"id": 9493, "materia": "adua", "nivel": 1, "enunciado": "A Tarifa Externa Comum (TEC) define:", "opcoes": ["As alíquotas do imposto de importação no Mercosul", "O valor do dólar", "O frete marítimo", "O salário dos despachantes"], "explicacao": ""}, {"id": 9494, "materia": "adua", "nivel": 1, "enunciado": "O imposto de importação está sujeito à anterioridade de exercício e à noventena?", "opcoes": ["Não, é exceção às duas", "Sim, às duas", "Só à noventena", "Só à de exercício"], "explicacao": "CF, art. 150, § 1º."}, {"id": 9495, "materia": "adua", "nivel": 2, "enunciado": "No despacho de importação, o canal amarelo significa:", "opcoes": ["Exame documental", "Verificação física obrigatória", "Liberação automática", "Perdimento"], "explicacao": ""}, {"id": 9496, "materia": "adua", "nivel": 2, "enunciado": "O canal cinza é usado quando há:", "opcoes": ["Indícios de fraude, como subfaturamento, com procedimento especial de controle", "Mercadoria perecível", "Remessa de pequeno valor", "Bagagem de viajante"], "explicacao": ""}, {"id": 9497, "materia": "adua", "nivel": 2, "enunciado": "O desembaraço aduaneiro é o ato que:", "opcoes": ["Registra a conclusão da conferência aduaneira", "Inicia o despacho", "Cobra o frete", "Aplica multa"], "explicacao": "Regulamento Aduaneiro, art. 571."}, {"id": 9498, "materia": "adua", "nivel": 2, "enunciado": "Mercadoria desembaraçada pode passar por revisão aduaneira?", "opcoes": ["Sim, enquanto não decaído o direito de constituir o crédito", "Não, nunca", "Só em 30 dias", "Só se o importador pedir"], "explicacao": "Regulamento Aduaneiro, art. 638."}, {"id": 9499, "materia": "adua", "nivel": 2, "enunciado": "A admissão temporária permite:", "opcoes": ["Importar bens para permanecer por prazo fixado e depois retornar, com suspensão de tributos", "Importar para venda definitiva sem imposto", "Exportar sem retorno", "Doar ao governo"], "explicacao": ""}, {"id": 9500, "materia": "adua", "nivel": 2, "enunciado": "As modalidades de drawback são:", "opcoes": ["Suspensão, isenção e restituição", "Importação, exportação e trânsito", "Verde, amarelo e vermelho", "Simples, composto e misto"], "explicacao": ""}, {"id": 9501, "materia": "adua", "nivel": 3, "enunciado": "A pena de perdimento é aplicada em infrações consideradas:", "opcoes": ["Dano ao Erário", "Leves", "Formais sem prejuízo", "Erros de digitação"], "explicacao": "Decreto-Lei 1.455/1976, art. 23."}, {"id": 9502, "materia": "adua", "nivel": 3, "enunciado": "Se a mercadoria sujeita a perdimento foi consumida ou não é localizada, a pena é convertida em:", "opcoes": ["Multa equivalente ao valor aduaneiro", "Advertência", "Prisão", "Nenhuma sanção"], "explicacao": "Decreto-Lei 1.455/1976, art. 23, § 3º."}, {"id": 9503, "materia": "adua", "nivel": 3, "enunciado": "A interposição fraudulenta na importação consiste em:", "opcoes": ["Ocultar o real comprador, vendedor ou responsável pela operação", "Pagar o imposto em dia", "Declarar corretamente", "Usar despachante"], "explicacao": ""}, {"id": 9504, "materia": "adua", "nivel": 3, "enunciado": "O subfaturamento na importação é:", "opcoes": ["Declarar valor inferior ao real para pagar menos tributos", "Declarar valor maior que o real", "Pagar em dólar", "Atrasar o pagamento"], "explicacao": ""}, {"id": 9505, "materia": "adua", "nivel": 3, "enunciado": "A base de cálculo do IPI na importação é:", "opcoes": ["O valor aduaneiro acrescido do imposto de importação e encargos cambiais", "Somente o frete", "O preço de varejo no Brasil", "O peso da mercadoria"], "explicacao": "CTN, art. 47, I."}, {"id": 9506, "materia": "adua", "nivel": 3, "enunciado": "O AFRMM incide sobre:", "opcoes": ["O frete do transporte aquaviário de carga", "O transporte aéreo de passageiros", "A venda de combustível", "A renda do importador"], "explicacao": "Lei 10.893/2004."}, {"id": 9507, "materia": "adua", "nivel": 3, "enunciado": "O Operador Econômico Autorizado (OEA) é:", "opcoes": ["Empresa certificada como de baixo risco, com mais agilidade no controle aduaneiro", "Um servidor da Receita", "Um despachante qualquer", "Uma transportadora estatal"], "explicacao": ""}, {"id": 9508, "materia": "adua", "nivel": 4, "enunciado": "No Incoterm FOB, o vendedor:", "opcoes": ["Entrega a mercadoria a bordo do navio no porto de embarque", "Paga o frete até o destino", "Entrega no armazém do comprador", "Paga os tributos de importação"], "explicacao": ""}, {"id": 9509, "materia": "adua", "nivel": 4, "enunciado": "No Incoterm CIF, o vendedor paga:", "opcoes": ["Custo, seguro e frete até o porto de destino", "Apenas o custo", "Tributos de importação no destino", "Nada além da mercadoria"], "explicacao": "O risco passa ao comprador no embarque."}, {"id": 9510, "materia": "adua", "nivel": 4, "enunciado": "O Incoterm EXW representa:", "opcoes": ["A menor obrigação do vendedor, que entrega no próprio estabelecimento", "A maior obrigação do vendedor", "Entrega no destino com tributos pagos", "Entrega a bordo"], "explicacao": ""}, {"id": 9511, "materia": "adua", "nivel": 4, "enunciado": "O dumping é:", "opcoes": ["Exportar a preço inferior ao valor normal no mercado do exportador, causando dano à indústria do importador", "Exportar com lucro", "Importar matéria-prima", "Pagar impostos em excesso"], "explicacao": ""}, {"id": 9512, "materia": "adua", "nivel": 4, "enunciado": "A medida de salvaguarda protege a indústria nacional contra:", "opcoes": ["Surto de importações, mesmo sem prática desleal", "Dumping apenas", "Subsídios apenas", "Contrabando"], "explicacao": ""}, {"id": 9513, "materia": "adua", "nivel": 4, "enunciado": "A cláusula da nação mais favorecida, da OMC, determina que:", "opcoes": ["Vantagem dada a um membro deve ser estendida a todos os membros", "Cada país escolhe seus parceiros livremente sem regra", "Só os países ricos têm vantagens", "Os tributos devem ser iguais a zero"], "explicacao": "Exceção: acordos regionais como o Mercosul."}, {"id": 9514, "materia": "adua", "nivel": 4, "enunciado": "A Zona Franca de Manaus tem previsão constitucional até:", "opcoes": ["2073", "2030", "2100", "2050"], "explicacao": "ADCT, art. 92-A (EC 83/2014)."}, {"id": 9515, "materia": "adua", "nivel": 3, "enunciado": "A mercadoria que fica em recinto alfandegado sem despacho após o prazo legal é considerada:", "opcoes": ["Abandonada, sujeita a perdimento", "Liberada automaticamente", "Doada ao importador", "Isenta"], "explicacao": ""}, {"id": 9516, "materia": "adua", "nivel": 2, "enunciado": "A bagagem do viajante, para fins aduaneiros, compreende bens:", "opcoes": ["Para uso ou consumo pessoal ou para presentear, compatíveis com a viagem, sem fim comercial", "Para revenda", "Em quantidade comercial", "Qualquer mercadoria"], "explicacao": ""}, {"id": 9517, "materia": "adua", "nivel": 1, "enunciado": "A precedência da autoridade aduaneira na zona primária está prevista na:", "opcoes": ["Constituição Federal, art. 37, XVIII", "Lei Maria da Penha", "CLT", "Lei de Licitações"], "explicacao": ""}, {"id": 9518, "materia": "dados", "nivel": 0, "enunciado": "Em SQL, o comando usado para consultar dados é:", "opcoes": ["SELECT", "INSERT", "DELETE", "DROP"], "explicacao": ""}, {"id": 9519, "materia": "dados", "nivel": 0, "enunciado": "Em SQL, o comando que insere novas linhas em uma tabela é:", "opcoes": ["INSERT", "SELECT", "UPDATE", "ALTER"], "explicacao": ""}, {"id": 9520, "materia": "dados", "nivel": 0, "enunciado": "Em SQL, o comando que altera valores de linhas existentes é:", "opcoes": ["UPDATE", "INSERT", "CREATE", "GRANT"], "explicacao": ""}, {"id": 9521, "materia": "dados", "nivel": 0, "enunciado": "Em SQL, a cláusula que filtra linhas é:", "opcoes": ["WHERE", "ORDER BY", "FROM", "AS"], "explicacao": ""}, {"id": 9522, "materia": "dados", "nivel": 0, "enunciado": "Em SQL, a cláusula que ordena o resultado é:", "opcoes": ["ORDER BY", "GROUP BY", "WHERE", "HAVING"], "explicacao": ""}, {"id": 9523, "materia": "dados", "nivel": 0, "enunciado": "A chave primária de uma tabela:", "opcoes": ["Identifica cada linha de forma única", "Pode se repetir livremente", "Liga sempre a outra tabela", "É opcional e pode ser nula"], "explicacao": ""}, {"id": 9524, "materia": "dados", "nivel": 0, "enunciado": "A chave estrangeira serve para:", "opcoes": ["Referenciar a chave primária de outra tabela", "Criptografar dados", "Ordenar a tabela", "Apagar linhas"], "explicacao": ""}, {"id": 9525, "materia": "dados", "nivel": 0, "enunciado": "Um arquivo CSV armazena dados:", "opcoes": ["Em texto, com valores separados por delimitador", "Em imagem", "Somente em binário compactado", "Em áudio"], "explicacao": ""}, {"id": 9526, "materia": "dados", "nivel": 0, "enunciado": "Dados pessoais, pela LGPD, são informações relacionadas a:", "opcoes": ["Pessoa natural identificada ou identificável", "Apenas empresas", "Somente órgãos públicos", "Animais"], "explicacao": "Lei 13.709/2018, art. 5º, I."}, {"id": 9527, "materia": "dados", "nivel": 0, "enunciado": "Na LGPD, o titular é:", "opcoes": ["A pessoa natural a quem os dados se referem", "A empresa que trata os dados", "O governo", "O programador"], "explicacao": "Art. 5º, V."}, {"id": 9528, "materia": "dados", "nivel": 0, "enunciado": "Um gráfico de pizza é mais indicado para mostrar:", "opcoes": ["Partes de um todo", "Evolução ao longo do tempo com muitos pontos", "Correlação entre duas variáveis", "Distribuição de frequência contínua"], "explicacao": ""}, {"id": 9529, "materia": "dados", "nivel": 0, "enunciado": "Para mostrar a evolução de uma variável no tempo, o gráfico mais adequado é o de:", "opcoes": ["Linhas", "Pizza", "Mapa de calor se