2, "materia": "cont", "nivel": 4, "enunciado": "A reserva de lucros a realizar pode ser constituída quando:", "opcoes": ["O dividendo obrigatório superar a parcela realizada do lucro", "Houver prejuízo", "O capital for reduzido", "Sempre por decisão do auditor"], "explicacao": "Lei 6.404, art. 197."}, {"id": 9833, "materia": "afo", "nivel": 0, "enunciado": "A receita pública que entra nos cofres e pertence ao Estado, prevista no orçamento, é a receita:", "opcoes": ["Orçamentária", "Extraorçamentária", "Patrimonial apenas", "Fictícia"], "explicacao": ""}, {"id": 9834, "materia": "afo", "nivel": 1, "enunciado": "Cauções e depósitos de terceiros recebidos pelo Estado são receitas:", "opcoes": ["Extraorçamentárias", "Orçamentárias correntes", "De capital", "Tributárias"], "explicacao": ""}, {"id": 9835, "materia": "afo", "nivel": 2, "enunciado": "A despesa com investimentos, como obras, é despesa:", "opcoes": ["De capital", "Corrente", "Extraorçamentária", "De custeio"], "explicacao": "Lei 4.320, art. 12."}, {"id": 9836, "materia": "afo", "nivel": 4, "enunciado": "A sessão legislativa não será interrompida sem a aprovação do projeto de:", "opcoes": ["Lei de diretrizes orçamentárias", "Lei orçamentária anual", "Plano plurianual", "Código tributário"], "explicacao": "CF, art. 57, § 2º."}, {"id": 9837, "materia": "afo", "nivel": 4, "enunciado": "O novo arcabouço fiscal da União foi instituído pela:", "opcoes": ["Lei Complementar 200/2023", "Lei Complementar 101/2000", "EC 95/2016", "Lei 4.320/64"], "explicacao": ""}, {"id": 9838, "materia": "trib", "nivel": 2, "enunciado": "A contribuição de melhoria tem como fato gerador:", "opcoes": ["Valorização imobiliária decorrente de obra pública", "Serviço de coleta de lixo", "Renda", "Propriedade de veículo"], "explicacao": "CTN, art. 81."}, {"id": 9839, "materia": "est", "nivel": 1, "enunciado": "Amplitude total de um conjunto é:", "opcoes": ["O maior valor menos o menor", "A média menos a moda", "A soma dos valores", "O número de elementos"], "explicacao": ""}, {"id": 9840, "materia": "est", "nivel": 2, "enunciado": "O coeficiente de variação permite comparar:", "opcoes": ["A dispersão relativa de conjuntos com médias diferentes", "Somente médias", "Somente modas", "Tamanhos de amostras"], "explicacao": ""}, {"id": 9841, "materia": "est", "nivel": 3, "enunciado": "Na regressão linear simples y = a + bx, b representa:", "opcoes": ["A variação esperada de y para cada unidade de x", "O valor de y quando x = 0", "O erro", "A correlação"], "explicacao": ""}, {"id": 9842, "materia": "aud", "nivel": 0, "enunciado": "Papéis de trabalho pertencem:", "opcoes": ["Ao auditor", "À empresa auditada", "À Receita Federal", "Ao CRC"], "explicacao": "NBC TA 230."}, {"id": 9843, "materia": "aud", "nivel": 1, "enunciado": "A auditoria interna deve se reportar, para ter independência, preferencialmente:", "opcoes": ["Ao conselho ou comitê de auditoria", "Ao gerente da área auditada", "Ao setor de compras", "Ao contador"], "explicacao": ""}, {"id": 9844, "materia": "aud", "nivel": 2, "enunciado": "O teste de corte (cut-off) verifica se as transações foram registradas:", "opcoes": ["No período correto", "Pelo valor de mercado", "Pela pessoa certa", "Em moeda estrangeira"], "explicacao": ""}, {"id": 9845, "materia": "aud", "nivel": 3, "enunciado": "O auditor sucessor, antes de aceitar o trabalho, deve:", "opcoes": ["Comunicar-se com o auditor antecessor", "Ignorar o trabalho anterior", "Refazer todas as auditorias anteriores", "Pedir autorização à CVM sempre"], "explicacao": "NBC TA 510 e NBC PA."}, {"id": 9846, "materia": "aud", "nivel": 4, "enunciado": "Saldos iniciais, em primeira auditoria, exigem que o auditor:", "opcoes": ["Obtenha evidência de que não contêm distorções que afetem o período atual", "Ignore os saldos iniciais", "Emita abstenção automática", "Aceite sem análise"], "explicacao": "NBC TA 510."}, {"id": 9847, "materia": "aud", "nivel": 1, "enunciado": "O relatório do auditor independente é dirigido, em regra:", "opcoes": ["Aos acionistas ou ao conselho, conforme o contrato", "Ao fisco", "Aos fornecedores", "Aos empregados"], "explicacao": ""}, {"id": 9848, "materia": "aud", "nivel": 2, "enunciado": "Um sistema de autorização por alçadas é controle:", "opcoes": ["Preventivo", "Detectivo", "Corretivo", "Inexistente"], "explicacao": ""}, {"id": 9849, "materia": "adua", "nivel": 0, "enunciado": "Desembaraçar uma mercadoria significa:", "opcoes": ["Liberá-la após a conferência aduaneira", "Destruí-la", "Exportá-la", "Classificá-la no Simples"], "explicacao": ""}, {"id": 9850, "materia": "adua", "nivel": 1, "enunciado": "O despachante aduaneiro atua:", "opcoes": ["Representando o importador ou exportador no despacho", "Como fiscal da Receita", "Como juiz", "Como transportador obrigatório"], "explicacao": ""}, {"id": 9851, "materia": "adua", "nivel": 2, "enunciado": "Na exportação, o despacho é feito, em regra, com base na:", "opcoes": ["Declaração Única de Exportação (DU-E)", "Declaração de imposto de renda", "Nota de empenho", "Licença municipal"], "explicacao": ""}, {"id": 9852, "materia": "adua", "nivel": 3, "enunciado": "A conferência aduaneira tem por finalidade:", "opcoes": ["Identificar o importador, verificar a mercadoria e a correção das informações", "Cobrar frete", "Liberar sem exame", "Emitir certidão negativa"], "explicacao": "Regulamento Aduaneiro, art. 564."}, {"id": 9853, "materia": "adua", "nivel": 4, "enunciado": "O valor aduaneiro inclui, pelo Acordo de Valoração, adotado no Brasil:", "opcoes": ["Frete e seguro até o porto ou ponto de entrada no país", "Somente o preço FOB sempre", "O ICMS", "O lucro do revendedor no Brasil"], "explicacao": "Regulamento Aduaneiro, art. 77."}, {"id": 9854, "materia": "eco", "nivel": 0, "enunciado": "Recessão é, em geral:", "opcoes": ["Queda da atividade econômica por um período", "Aumento do PIB", "Inflação baixa", "Alta das exportações"], "explicacao": ""}, {"id": 9855, "materia": "eco", "nivel": 1, "enunciado": "Estagflação é a combinação de:", "opcoes": ["Estagnação econômica com inflação", "Crescimento e deflação", "Pleno emprego e deflação", "Juros zero e superávit"], "explicacao": ""}, {"id": 9856, "materia": "eco", "nivel": 2, "enunciado": "A política cambial de câmbio flutuante significa que:", "opcoes": ["O mercado determina a taxa de câmbio, com intervenções eventuais", "O governo fixa a taxa", "Não há moeda estrangeira", "O câmbio é sempre igual a 1"], "explicacao": ""}, {"id": 9857, "materia": "eco", "nivel": 3, "enunciado": "A meta de inflação no Brasil é fixada pelo:", "opcoes": ["Conselho Monetário Nacional", "Copom", "Senado", "IBGE"], "explicacao": ""}, {"id": 9858, "materia": "eco", "nivel": 4, "enunciado": "No longo prazo, segundo a visão clássica, a moeda é:", "opcoes": ["Neutra, afetando apenas variáveis nominais", "Determinante do PIB real", "Irrelevante para preços", "Causa do desemprego estrutural"], "explicacao": ""}, {"id": 9859, "materia": "dados", "nivel": 0, "enunciado": "Backup serve para:", "opcoes": ["Guardar cópias de segurança dos dados", "Apagar arquivos", "Acelerar a internet", "Criar senhas"], "explicacao": ""}, {"id": 9860, "materia": "dados", "nivel": 1, "enunciado": "Na LGPD, o consentimento deve ser:", "opcoes": ["Livre, informado e inequívoco, para finalidade determinada", "Presumido sempre", "Verbal e sem registro", "Genérico para qualquer uso"], "explicacao": "Art. 5º, XII."}, {"id": 9861, "materia": "dados", "nivel": 2, "enunciado": "Em estatística descritiva para análise de dados, o histograma mostra:", "opcoes": ["A distribuição de frequências de uma variável numérica", "A relação entre duas categorias", "Partes de um todo", "A série temporal"], "explicacao": ""}, {"id": 9862, "materia": "dados", "nivel": 3, "enunciado": "Normalizar variáveis antes de um modelo de distância, como k-means, serve para:", "opcoes": ["Evitar que variáveis de escala maior dominem o resultado", "Apagar outliers", "Aumentar o número de clusters", "Rotular os dados"], "explicacao": ""}, {"id": 9863, "materia": "dados", "nivel": 4, "enunciado": "Data lakehouse combina características de:", "opcoes": ["Data lake e data warehouse", "OLTP e e-mail", "Planilha e editor de texto", "Backup e antivírus"], "explicacao": ""}, {"id": 9864, "materia": "cont", "nivel": 0, "enunciado": "Receita aumenta o:", "opcoes": ["Patrimônio líquido", "Passivo", "Ativo apenas sem efeito no PL", "Capital social"], "explicacao": ""}, {"id": 9865, "materia": "cont", "nivel": 1, "enunciado": "Despesa reduz o:", "opcoes": ["Patrimônio líquido", "Ativo apenas sem efeito no PL", "Passivo", "Capital social"], "explicacao": ""}, {"id": 9866, "materia": "cont", "nivel": 2, "enunciado": "O princípio (pressuposto) da continuidade supõe que a entidade:", "opcoes": ["Continuará operando no futuro previsível", "Será encerrada", "Será vendida", "Não terá lucro"], "explicacao": "Estrutura Conceitual."}, {"id": 9867, "materia": "cont", "nivel": 3, "enunciado": "As características qualitativas fundamentais da informação contábil são:", "opcoes": ["Relevância e representação fidedigna", "Comparabilidade e tempestividade", "Verificabilidade e compreensibilidade", "Prudência e conservadorismo"], "explicacao": "CPC 00 (R2)."}, {"id": 9868, "materia": "cont", "nivel": 4, "enunciado": "As características qualitativas de melhoria são:", "opcoes": ["Comparabilidade, verificabilidade, tempestividade e compreensibilidade", "Relevância e fidedignidade", "Prudência e neutralidade", "Materialidade e custo"], "explicacao": "CPC 00 (R2)."}, {"id": 9869, "materia": "afo", "nivel": 0, "enunciado": "O orçamento público autoriza:", "opcoes": ["As despesas a serem realizadas no exercício", "Só as receitas privadas", "Os salários de empresas privadas", "Os preços de mercado"], "explicacao": ""}, {"id": 9870, "materia": "afo", "nivel": 1, "enunciado": "O princípio do equilíbrio orçamentário busca que:", "opcoes": ["As despesas não superem as receitas", "As receitas sejam zero", "As despesas sejam secretas", "O orçamento seja plurianual"], "explicacao": ""}, {"id": 9871, "materia": "afo", "nivel": 2, "enunciado": "O princípio da não vinculação veda vincular receita de:", "opcoes": ["Impostos a órgão, fundo ou despesa, ressalvadas as exceções constitucionais", "Taxas a serviços", "Contribuições", "Multas"], "explicacao": "CF, art. 167, IV."}, {"id": 9872, "materia": "afo", "nivel": 3, "enunciado": "Transferências voluntárias, pela LRF, são recursos entregues a outro ente:", "opcoes": ["Que não decorram de determinação constitucional, legal ou destinadas ao SUS", "Por obrigação constitucional", "Só ao SUS", "Apenas para pessoal"], "explicacao": "LRF, art. 25."}, {"id": 9873, "materia": "afo", "nivel": 4, "enunciado": "É vedada a transferência voluntária para pagamento de:", "opcoes": ["Despesas com pessoal ativo, inativo e pensionista", "Obras", "Equipamentos", "Programas sociais"], "explicacao": "CF, art. 167, X."}, {"id": 9874, "materia": "trib", "nivel": 2, "enunciado": "A obrigação acessória, quando descumprida:", "opcoes": ["Converte-se em obrigação principal quanto à penalidade", "Desaparece", "Gera isenção", "Extingue o tributo"], "explicacao": "CTN, art. 113, § 3º."}, {"id": 9875, "materia": "trib", "nivel": 4, "enunciado": "A Lei Complementar que regulamentou o IBS e a CBS é a:", "opcoes": ["LC 214/2025", "LC 87/1996", "LC 116/2003", "LC 123/2006"], "explicacao": ""}, {"id": 9876, "materia": "est", "nivel": 0, "enunciado": "Em um dado comum, a probabilidade de sair o número 3 é:", "opcoes": ["1/6", "1/3", "1/2", "3/6"], "explicacao": ""}, {"id": 9877, "materia": "est", "nivel": 2, "enunciado": "Quartis dividem o conjunto ordenado em:", "opcoes": ["Quatro partes iguais", "Dez partes", "Cem partes", "Duas partes"], "explicacao": ""}, {"id": 9878, "materia": "aud", "nivel": 0, "enunciado": "Distorção, em auditoria, é a diferença entre o valor divulgado e o valor:", "opcoes": ["Exigido pela estrutura de relatório financeiro aplicável", "Que o diretor deseja", "Do ano anterior sempre", "Do concorrente"], "explicacao": "NBC TA 200."}, {"id": 9879, "materia": "aud", "nivel": 0, "enunciado": "O controle interno é responsabilidade principal da:", "opcoes": ["Administração da entidade", "Auditoria externa", "Receita Federal", "Clientela"], "explicacao": ""}, {"id": 9880, "materia": "aud", "nivel": 1, "enunciado": "O rodízio de funções entre empregados é um controle que ajuda a:", "opcoes": ["Dificultar e revelar fraudes", "Aumentar salários", "Evitar a auditoria", "Dispensar a contabilidade"], "explicacao": ""}, {"id": 9881, "materia": "aud", "nivel": 1, "enunciado": "Exigir duas assinaturas para cheques acima de certo valor é exemplo de:", "opcoes": ["Controle preventivo de autorização", "Procedimento analítico", "Circularização", "Evento subsequente"], "explicacao": ""}, {"id": 9882, "materia": "aud", "nivel": 2, "enunciado": "A revisão analítica que compara a margem bruta deste ano com a do ano anterior é:", "opcoes": ["Procedimento analítico", "Teste de controle", "Confirmação externa", "Inspeção física"], "explicacao": ""}, {"id": 9883, "materia": "adua", "nivel": 0, "enunciado": "Exportar significa:", "opcoes": ["Enviar bens ou serviços para outro país", "Comprar produto estrangeiro", "Vender no mercado interno", "Pagar imposto municipal"], "explicacao": ""}, {"id": 9884, "materia": "adua", "nivel": 0, "enunciado": "A alfândega é a repartição responsável por:", "opcoes": ["Controlar a entrada e a saída de mercadorias do país", "Emitir carteira de motorista", "Julgar crimes", "Recolher IPTU"], "explicacao": ""}, {"id": 9885, "materia": "adua", "nivel": 1, "enunciado": "Os tributos incidentes na importação incluem, em regra:", "opcoes": ["II, IPI, PIS/Cofins-Importação e ICMS", "Apenas IPTU", "Apenas ISS", "IR e IPVA"], "explicacao": ""}, {"id": 9886, "materia": "adua", "nivel": 2, "enunciado": "A alíquota específica do imposto de importação é cobrada:", "opcoes": ["Por unidade de medida, como quilo ou litro", "Sobre o valor aduaneiro", "Sobre o lucro", "Sobre o frete apenas"], "explicacao": "CTN, art. 20, I."}, {"id": 9887, "materia": "adua", "nivel": 2, "enunciado": "O ICMS na importação é devido ao estado:", "opcoes": ["Onde estiver situado o domicílio ou estabelecimento do destinatário", "Do porto de desembarque sempre", "De São Paulo", "Escolhido pelo exportador"], "explicacao": "CF, art. 155, § 2º, IX, a."}, {"id": 9888, "materia": "afo", "nivel": 0, "enunciado": "O pagamento é o último estágio da despesa e ocorre:", "opcoes": ["Após a regular liquidação", "Antes do empenho", "Antes da licitação", "Sem liquidação"], "explicacao": "Lei 4.320, art. 62."}, {"id": 9889, "materia": "afo", "nivel": 1, "enunciado": "Despesas correntes incluem, por exemplo:", "opcoes": ["Pessoal, material de consumo e juros", "Obras e equipamentos", "Compra de imóveis", "Amortização da dívida"], "explicacao": ""}, {"id": 9890, "materia": "afo", "nivel": 1, "enunciado": "A lei de responsabilidade fiscal tem como pilares:", "opcoes": ["Planejamento, transparência, controle e responsabilização", "Apenas punir prefeitos", "Aumentar tributos", "Privatizar empresas"], "explicacao": ""}, {"id": 9891, "materia": "afo", "nivel": 2, "enunciado": "Pela LRF, os instrumentos de transparência incluem:", "opcoes": ["Planos, orçamentos, LDO, prestações de contas, RREO e RGF", "Apenas o Diário Oficial", "Só o site do Senado", "Somente a LOA"], "explicacao": "LRF, art. 48."}, {"id": 9892, "materia": "trib", "nivel": 1, "enunciado": "O princípio da legalidade tributária exige que tributos sejam instituídos ou aumentados por:", "opcoes": ["Lei", "Decreto", "Portaria", "Instrução normativa"], "explicacao": "CF, art. 150, I."}, {"id": 9893, "materia": "trib", "nivel": 1, "enunciado": "O ITCMD incide sobre:", "opcoes": ["Transmissão causa mortis e doação", "Venda de imóveis entre vivos onerosa", "Serviços", "Veículos"], "explicacao": "CF, art. 155, I."}, {"id": 9894, "materia": "trib", "nivel": 1, "enunciado": "O ITBI incide sobre:", "opcoes": ["Transmissão onerosa de bens imóveis entre vivos", "Herança", "Doação", "Serviços"], "explicacao": "CF, art. 156, II."}, {"id": 9895, "materia": "cont", "nivel": 0, "enunciado": "O balanço patrimonial mostra:", "opcoes": ["A posição do ativo, do passivo e do PL em uma data", "O resultado do período", "Somente o caixa", "Os fluxos de caixa"], "explicacao": ""}, {"id": 9896, "materia": "cont", "nivel": 0, "enunciado": "Lucro é obtido quando:", "opcoes": ["As receitas superam as despesas", "As despesas superam as receitas", "O ativo é igual ao passivo", "Não há vendas"], "explicacao": ""}, {"id": 9897, "materia": "cont", "nivel": 1, "enunciado": "Uma empresa tem ativo circulante de R$ 150.000,00 e passivo circulante de R$ 100.000,00. Sua liquidez corrente é:", "opcoes": ["1,5", "0,67", "2", "50.000"], "explicacao": "Liquidez corrente = AC ÷ PC."}, {"id": 9898, "materia": "cont", "nivel": 1, "enunciado": "Uma empresa tem ativo circulante de R$ 80.000,00 e passivo circulante de R$ 100.000,00. Sua liquidez corrente é:", "opcoes": ["0,8", "1,25", "1,3", "-20.000"], "explicacao": "Liquidez corrente = AC ÷ PC."}, {"id": 9899, "materia": "cont", "nivel": 1, "enunciado": "Uma empresa tem ativo circulante de R$ 240.000,00 e passivo circulante de R$ 120.000,00. Sua liquidez corrente é:", "opcoes": ["2", "0,5", "2,5", "120.000"], "explicacao": "Liquidez corrente = AC ÷ PC."}, {"id": 9900, "materia": "cont", "nivel": 2, "enunciado": "Ativo circulante de R$ 90.000,00, estoques de R$ 30.000,00 e passivo circulante de R$ 60.000,00. A liquidez seca é:", "opcoes": ["1", "1,5", "0,5", "2"], "explicacao": "Liquidez seca = (AC − estoques) ÷ PC."}, {"id": 9901, "materia": "cont", "nivel": 1, "enunciado": "Com ativo circulante de R$ 500.000,00 e passivo circulante de R$ 320.000,00, o capital circulante líquido é:", "opcoes": ["R$ 180.000,00", "R$ 820.000,00", "R$ -180.000,00", "R$ 90.000,00"], "explicacao": "CCL = AC − PC."}, {"id": 9902, "materia": "cont", "nivel": 2, "enunciado": "Uma máquina custou R$ 50.000,00, tem valor residual de R$ 5.000,00 e vida útil de 5 anos. A depreciação anual pelo método linear é:", "opcoes": ["R$ 9.000,00", "R$ 10.000,00", "R$ 45.000,00", "R$ 18.000,00"], "explicacao": "(Custo − valor residual) ÷ vida útil."}, {"id": 9903, "materia": "cont", "nivel": 3, "enunciado": "Um bem de R$ 60.000,00, valor residual de R$ 0,00 e vida útil de 5 anos, depreciado linearmente, terá valor contábil, após 2 anos, de:", "opcoes": ["R$ 36.000,00", "R$ 24.000,00", "R$ 60.000,00", "R$ 54.000,00"], "explicacao": "Valor contábil = custo − depreciação acumulada."}, {"id": 9904, "materia": "cont", "nivel": 1, "enunciado": "Estoque inicial de R$ 10.000,00, compras de R$ 50.000,00 e estoque final de R$ 15.000,00. O custo das mercadorias vendidas (CMV) é:", "opcoes": ["R$ 45.000,00", "R$ 75.000,00", "R$ 35.000,00", "R$ 50.000,00"], "explicacao": "CMV = EI + compras − EF."}, {"id": 9905, "materia": "cont", "nivel": 0, "enunciado": "Receita líquida de R$ 100.000,00 e CMV de R$ 60.000,00. O lucro bruto é:", "opcoes": ["R$ 40.000,00", "R$ 160.000,00", "R$ 60.000,00", "R$ 100.000,00"], "explicacao": "Lucro bruto = receita líquida − CMV."}, {"id": 9906, "materia": "cont", "nivel": 2, "enunciado": "Um produto é vendido por R$ 50,00 e tem custos e despesas variáveis de R$ 30,00 por unidade. A margem de contribuição unitária é:", "opcoes": ["R$ 20,00", "R$ 80,00", "R$ 30,00", "R$ 10,00"], "explicacao": "MC = preço − custos e despesas variáveis."}, {"id": 9907, "materia": "cont", "nivel": 3, "enunciado": "Custos fixos de R$ 20.000,00, preço de venda de R$ 50,00 e custo variável unitário de R$ 30,00. O ponto de equilíbrio contábil, em unidades, é:", "opcoes": ["1.000 unidades", "400 unidades", "666,67 unidades", "2.000 unidades"], "explicacao": "PE = custos fixos ÷ margem de contribuição unitária."}, {"id": 9908, "materia": "cont", "nivel": 2, "enunciado": "Lucro líquido de R$ 50.000,00 e patrimônio líquido de R$ 250.000,00. O retorno sobre o patrimônio líquido (ROE) é:", "opcoes": ["20%", "5%", "40%", "10%"], "explicacao": "ROE = lucro líquido ÷ PL."}, {"id": 9909, "materia": "cont", "nivel": 2, "enunciado": "Lucro líquido de R$ 30.000,00 e patrimônio líquido de R$ 200.000,00. O retorno sobre o patrimônio líquido (ROE) é:", "opcoes": ["15%", "6,67%", "30%", "7,5%"], "explicacao": "ROE = lucro líquido ÷ PL."}, {"id": 9910, "materia": "cont", "nivel": 3, "enunciado": "Uma S.A. teve lucro líquido de R$ 100.000,00. Pela regra geral, quanto destina à reserva legal (sem considerar o limite de 20% do capital)?", "opcoes": ["R$ 5.000,00", "R$ 10.000,00", "R$ 20.000,00", "R$ 25.000,00"], "explicacao": "Lei 6.404/1976, art. 193: 5% do lucro líquido."}, {"id": 9911, "materia": "cont", "nivel": 3, "enunciado": "Num balanço com ativo total de R$ 1.000.000,00 e capitais de terceiros de R$ 600.000,00, a participação dos capitais de terceiros no ativo total é de:", "opcoes": ["60%", "40%", "150%", "30%"], "explicacao": "Capitais de terceiros ÷ ativo total."}, {"id": 9912, "materia": "cont", "nivel": 3, "enunciado": "Num balanço com ativo total de R$ 500.000,00 e capitais de terceiros de R$ 100.000,00, a participação dos capitais de terceiros no ativo total é de:", "opcoes": ["20%", "80%", "25%", "10%"], "explicacao": "Capitais de terceiros ÷ ativo total."}, {"id": 9913, "materia": "cont", "nivel": 4, "enunciado": "Estoque inicial: 10 unidades a R$ 5,00. Compra: 10 unidades a R$ 7,00. Venda de 15 unidades. Pelo PEPS, o CMV é:", "opcoes": ["R$ 85,00", "R$ 95,00", "R$ 90,00", "R$ 105,00"], "explicacao": "Saem primeiro as 10 a R$ 5 (R$ 50) e depois 5 a R$ 7 (R$ 35)."}, {"id": 9914, "materia": "est", "nivel": 1, "enunciado": "Para os dados 2, 4, 4, 5, 7, 8, a média aritmética é:", "opcoes": ["5", "4,5", "30", "4"], "explicacao": "Soma ÷ quantidade."}, {"id": 9915, "materia": "est", "nivel": 1, "enunciado": "Para os dados 2, 4, 4, 5, 7, 8, a moda é:", "opcoes": ["4", "5", "8", "2"], "explicacao": "Valor mais frequente."}, {"id": 9916, "materia": "est", "nivel": 2, "enunciado": "Para os dados 2, 4, 4, 5, 7, 8, a amplitude é:", "opcoes": ["6", "8", "5", "10"], "explicacao": "Maior − menor."}, {"id": 9917, "materia": "est", "nivel": 1, "enunciado": "Para os dados 10, 12, 15, 15, 18, a média aritmética é:", "opcoes": ["14", "15", "70", "21"], "explicacao": "Soma ÷ quantidade."}, {"id": 9918, "materia": "est", "nivel": 1, "enunciado": "Para os dados 10, 12, 15, 15, 18, a moda é:", "opcoes": ["15", "14", "18", "10"], "explicacao": "Valor mais frequente."}, {"id": 9919, "materia": "est", "nivel": 2, "enunciado": "Para os dados 10, 12, 15, 15, 18, a amplitude é:", "opcoes": ["8", "18", "14", "28"], "explicacao": "Maior − menor."}, {"id": 9920, "materia": "est", "nivel": 1, "enunciado": "Para os dados 1, 3, 3, 3, 5, 9, 11, a moda é:", "opcoes": ["3", "5", "11", "1"], "explicacao": "Valor mais frequente."}, {"id": 9921, "materia": "est", "nivel": 2, "enunciado": "Para os dados 1, 3, 3, 3, 5, 9, 11, a amplitude é:", "opcoes": ["10", "11", "5", "12"], "explicacao": "Maior − menor."}, {"id": 9922, "materia": "est", "nivel": 3, "enunciado": "A variância populacional dos dados 1, 2, 3, 4, 5 é:", "opcoes": ["2", "2,5", "3", "1"], "explicacao": "Média dos quadrados dos desvios em relação à média."}, {"id": 9923, "materia": "est", "nivel": 3, "enunciado": "A variância populacional dos dados 1, 3, 5, 7 é:", "opcoes": ["5", "6,67", "4", "6"], "explicacao": "Média dos quadrados dos desvios em relação à média."}, {"id": 9924, "materia": "est", "nivel": 2, "enunciado": "Um conjunto tem média 50 e desvio padrão 5. O coeficiente de variação é:", "opcoes": ["10%", "5%", "20%", "15%"], "explicacao": "CV = desvio padrão ÷ média."}, {"id": 9925, "materia": "est", "nivel": 2, "enunciado": "Um conjunto tem média 200 e desvio padrão 30. O coeficiente de variação é:", "opcoes": ["15%", "6,67%", "30%", "22,5%"], "explicacao": "CV = desvio padrão ÷ média."}, {"id": 9926, "materia": "est", "nivel": 1, "enunciado": "Se a variância de um conjunto é 25, o desvio padrão é:", "opcoes": ["5", "25", "12,5", "625"], "explicacao": "Raiz quadrada da variância."}, {"id": 9927, "materia": "est", "nivel": 1, "enunciado": "Se a variância de um conjunto é 81, o desvio padrão é:", "opcoes": ["9", "81", "40,5", "6.561"], "explicacao": "Raiz quadrada da variância."}, {"id": 9928, "materia": "est", "nivel": 1, "enunciado": "Se a variância de um conjunto é 144, o desvio padrão é:", "opcoes": ["12", "144", "72", "20.736"], "explicacao": "Raiz quadrada da variância."}, {"id": 9929, "materia": "est", "nivel": 3, "enunciado": "Se todos os valores de um conjunto forem multiplicados por 2, a variância fica multiplicada por:", "opcoes": ["4", "2", "1 (não muda)", "6"], "explicacao": "Var(kX) = k²·Var(X)."}, {"id": 9930, "materia": "est", "nivel": 3, "enunciado": "Se todos os valores de um conjunto forem multiplicados por 3, a variância fica multiplicada por:", "opcoes": ["9", "3", "1 (não muda)", "6"], "explicacao": "Var(kX) = k²·Var(X)."}, {"id": 9931, "materia": "est", "nivel": 4, "enunciado": "Numa amostra de 100 elementos com desvio padrão 10, o erro padrão da média é:", "opcoes": ["1", "0,1", "10", "2"], "explicacao": "Erro padrão = σ ÷ √n."}, {"id": 9932, "materia": "est", "nivel": 4, "enunciado": "Numa amostra de 400 elementos com desvio padrão 40, o erro padrão da média é:", "opcoes": ["2", "0,1", "40", "4"], "explicacao": "Erro padrão = σ ÷ √n."}, {"id": 9933, "materia": "est", "nivel": 3, "enunciado": "Uma variável X tem média 10 e desvio padrão 2. O valor padronizado (escore z) de X = 14 é:", "opcoes": ["2", "4", "7", "1,4"], "explicacao": "z = (14 − 10) ÷ 2."}, {"id": 9934, "materia": "est", "nivel": 4, "enunciado": "Num teste com P(A) = 0,3 e P(B) = 0,5, sendo A e B independentes, P(A e B) é:", "opcoes": ["0,15", "0,8", "0,2", "0,35"], "explicacao": "Independentes: multiplica-se."}, {"id": 9935, "materia": "est", "nivel": 4, "enunciado": "Se P(A) = 0,4, P(B) = 0,5 e P(A e B) = 0,2, então P(A ou B) é:", "opcoes": ["0,7", "0,9", "0,2", "0,1"], "explicacao": "P(A ∪ B) = 0,4 + 0,5 − 0,2."}, {"id": 9936, "materia": "eco", "nivel": 3, "enunciado": "Quando o preço de um bem sobe 10%, a quantidade demandada cai 20%. A demanda é:", "opcoes": ["Elástica", "Inelástica", "Unitária", "Perfeitamente inelástica"], "explicacao": "Elasticidade = 20% ÷ 10% = 2 (em módulo); maior que 1 é elástica, menor que 1 é inelástica."}, {"id": 9937, "materia": "eco", "nivel": 3, "enunciado": "Com propensão marginal a consumir de 0,8, o multiplicador keynesiano dos gastos é:", "opcoes": ["5", "0,8", "0,2", "10"], "explicacao": "k = 1 ÷ (1 − PMgC)."}, {"id": 9938, "materia": "eco", "nivel": 3, "enunciado": "Com propensão marginal a consumir de 0,75, o multiplicador keynesiano dos gastos é:", "opcoes": ["4", "0,75", "0,25", "8"], "explicacao": "k = 1 ÷ (1 − PMgC)."}, {"id": 9939, "materia": "eco", "nivel": 3, "enunciado": "Com propensão marginal a consumir de 0,5, o multiplicador keynesiano dos gastos é:", "opcoes": ["2", "0,5", "4", "3"], "explicacao": "k = 1 ÷ (1 − PMgC)."}, {"id": 9940, "materia": "eco", "nivel": 4, "enunciado": "Uma aplicação rende 10% num ano em que a inflação foi de 4%. A taxa real de juros é de aproximadamente:", "opcoes": ["5,77%", "7%", "14%", "10%"], "explicacao": "(1 + nominal) ÷ (1 + inflação) − 1."}, {"id": 9941, "materia": "eco", "nivel": 4, "enunciado": "Uma aplicação rende 15% num ano em que a inflação foi de 5%. A taxa real de juros é de aproximadamente:", "opcoes": ["9,52%", "11%", "20%", "15%"], "explicacao": "(1 + nominal) ÷ (1 + inflação) − 1."}, {"id": 9942, "materia": "eco", "nivel": 3, "enunciado": "O PIB nominal é 1.100 e o PIB real é 1.000 (em bilhões). O deflator do PIB é:", "opcoes": ["110", "90,91", "100", "10"], "explicacao": "Deflator = PIB nominal ÷ PIB real × 100."}, {"id": 9943, "materia": "eco", "nivel": 2, "enunciado": "Pela ótica da despesa, com consumo de 600, investimento de 200, gastos do governo de 150, exportações de 100 e importações de 80, o PIB é:", "opcoes": ["970", "1.130", "950", "1.050"], "explicacao": "PIB = C + I + G + (X − M)."}, {"id": 9944, "materia": "eco", "nivel": 4, "enunciado": "Uma taxa de 2% ao mês, capitalizada mensalmente, equivale a que taxa ao trimestre?", "opcoes": ["6,12%", "6%", "8%", "6,02%"], "explicacao": "(1,02)³ − 1 = 0,061208."}, {"id": 9945, "materia": "eco", "nivel": 4, "enunciado": "Um investimento de R$ 1.000,00 hoje gera R$ 1.100,00 daqui a 1 ano. Com taxa de desconto de 10% ao ano, o VPL é:", "opcoes": ["Zero", "R$ 100,00", "R$ 1.100,00", "R$ −100,00"], "explicacao": "1.100 ÷ 1,1 − 1.000 = 0."}, {"id": 9946, "materia": "eco", "nivel": 3, "enunciado": "Se o PIB cresceu de 1.000 para 1.050 (em termos reais), a taxa de crescimento foi de:", "opcoes": ["5%", "50%", "0,5%", "10%"], "explicacao": "50 ÷ 1.000."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes where id < 1000000));
select materia, count(*) as questoes from public.questoes where materia in ('cont','afo','aud','eco','adua','dados','est','trib') group by materia order by materia;
select count(*) as total_de_questoes from public.questoes;
